  "type": "vocab",
  "skill": "vocab",
  "level": "hard",
  "title": "Word in context",
  "prompt": "Which choice completes the text with the most logical and precise word?",
  "stem": "He had a certain ___ for tangible evidence, such as footprints and cigarette ash, and would maintain that, taken by themselves, they would never enable a detective to solve a problem.",
