  "fixed": "Not only does she see and hear practically everything that goes on, but she draws amazingly neat and apposite deductions from the facts that come under her notice.",
  "rule": "'Apposite' means strikingly appropriate or to the point. The deductions are called 'neat' and are drawn straight from the facts, so they fit the situation well.",
