  "fixed": "Therefore, why not wait in ambush for Conrad behind the door, and when he entered bring down a chair, or one of the decrepit pictures, smartly on to his head.",
  "rule": "'Decrepit' means old, worn out, and falling apart. Tuppence pictures smashing one over a man's head, which suits battered old pictures.",
